function puatPort(): int { $s=stream_socket_server('tcp://127.0.0.1:0',$e,$m);if(!is_resource($s))throw new RuntimeException("SETUP_FAILURE: $m");$n=(string)stream_socket_get_name($s,false);fclose($s);return(int)substr($n,strrpos($n,':')+1); }
