function puatStop(?array &$server): void { if($server===null)return;[$process,$pipes]=$server;if(proc_get_status($process)['running'])proc_terminate($process,15);$deadline=microtime(true)+.3;while(proc_get_status($process)['running']&&microtime(true)<$deadline)usleep(10000);if(proc_get_status($process)['running'])proc_terminate($process,9);foreach($pipes as$pipe){stream_get_contents($pipe);fclose($pipe);}proc_close($process);$server=null; }
