$db->set_charset('utf8mb4');$token=bin2hex(random_bytes(8));$email="token.actor.$token@shlz.ru";$root=sys_get_temp_dir().'/fmonitor2-session-storage-tests/task-'.$token;$actor=0;$role=0;$server=null;
