    $code='token-role-'.$token;$q=$db->prepare("INSERT INTO fm2_pilot_roles(code,name,description,status,source_updated_at)VALUES(?,'Token role','test',1,?)");$q->bind_param('ss',$code,$now);$q->execute();$role=(int)$db->insert_id;$db->query("INSERT INTO fm2_pilot_role_permissions(role_id,permission)VALUES($role,'access.administer')");$db->query("INSERT INTO fm2_pilot_user_roles(user_id,role_id,origin,assigned_at)VALUES($actor,$role,'test','$now')");
    $csrf=str_repeat('d',64);$original=serialize(['auth_user_id'=>$actor,'auth_email'=>$email,'auth_csrf'=>$csrf]);$owner=puatOwner($root,[32=>[str_repeat("\x41",32)],16=>[str_repeat("\x42",16)],12=>[str_repeat("\x43",12)]]);$started=$owner->start(null);$id=(string)$started->currentSessionId();assertSameValue('OK',$owner->writeCommit($id,$original)->status()->name,'canonical no-flash state committed');$owner->close();
    $environment=array_replace($_ENV,['FMONITOR_DB_HOST'=>getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1','FMONITOR_DB_PORT'=>getenv('FMONITOR_TEST_DB_PORT')?:'23306','FMONITOR_DB_NAME'=>getenv('FMONITOR_TEST_DB_NAME')?:'fmonitor2_test','FMONITOR_DB_USER'=>getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root','FMONITOR_DB_PASSWORD'=>getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local','FMONITOR_SESSION_STATE_ROOT'=>$root,'FMONITOR_SESSION_INSTANCE'=>'http_v7','FMONITOR_TRUSTED_REQUEST_SCHEME'=>'http']);
    $server=puatStart(dirname(__DIR__).'/Support/pilot_session_storage_user_access_router.php',$environment);[$status,,$body]=puatGet($server[2],"fm2auth_{$server[2]}=$id");assertSameValue(200,$status,'no-flash UserAccess GET succeeds');assertSameValue(1,preg_match('/name="csrfToken" value="([0-9a-f]{32})"/D',$body,$match),'one action token rendered');
