    $restore=puatOwner($root,[16=>[str_repeat("\x45",16)],12=>[str_repeat("\x46",12)]]);assertSameValue('OK',$restore->writeCommit($id,$original)->status()->name,'no-flash state restored for write fault');$restore->close();$server=puatStart(dirname(__DIR__).'/Support/pilot_session_storage_user_access_fault_router.php',$environment);[$faultStatus,$faultHeaders,$faultBody]=puatGet($server[2],"fm2auth_{$server[2]}=$id");assertSameValue(503,$faultStatus,'token commit fault maps unavailable');assertSameValue("Service unavailable.\n",$faultBody,'buffered token page discarded');assertSameValue([],array_intersect(array_keys($faultHeaders),['location','set-cookie']),'no success headers on token fault');$trace=(string)file_get_contents($root.'/user-access-fault-trace.jsonl');assertSameValue(1,preg_match_all('/"operation":"rename","artifact":"committed","ordinal":1,"outcome":"native_false"/',$trace),'exact token publication fault reached once');assertSameValue($original,file_get_contents($root.'/sessions/http_v7/s-'.$id.'.session'),'token fault preserves prior state');
